t.script:
/**/
                // ── Data from controller (read from JSON data islands) ──
                var allDevices = JSON.parse(document.getElementById('map-devices-data').textContent);
                var allMarkers = JSON.parse(document.getElementById('map-markers-data').textContent);
                var departments = JSON.parse(document.getElementById('map-departments-data').textContent);
                var __mapMeta = JSON.parse(document.getElementById('map-meta-data').textContent);
                var isManager = __mapMeta.is_manager;

                // ── State ──
                var currentToggle = 'all';
                var mapEmpMarkers = [];
                var mapDeviceMarkers = [];

                // ── Unique color per employee ──
                var empColorCache = {};
                function empColor(empId) {
                    if (empColorCache[empId]) return empColorCache[empId];
                    var hue = (empId * 137.508) % 360;
                    empColorCache[empId] = 'hsl(' + Math.round(hue) + ',65%,42%)';
                    return empColorCache[empId];
                }
                function empColorLight(empId) {
                    var hue = (empId * 137.508) % 360;
                    return 'hsl(' + Math.round(hue) + ',55%,65%)';
                }

                // ── Init dates ──
                document.getElementById('date-from').value = __mapMeta.date_from;
                document.getElementById('date-to').value = __mapMeta.date_to;

                // ── Populate department dropdown ──
                var deptSel = document.getElementById('dept-filter');
                departments.forEach(function(d) {
                    var o = document.createElement('option');
                    o.value = d.id; o.textContent = d.name;
                    deptSel.appendChild(o);
                });

                // ── Init map ──
                var map = L.map('map').setView([23.8103, 90.4125], 6);
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
                    maxZoom: 19
                }).addTo(map);

                // ══════════════════════════════════════════════════════════════
                // DEVICE MARKERS (always on map)
                // ══════════════════════════════════════════════════════════════
                function buildDeviceMarkers() {
                    mapDeviceMarkers.forEach(function(m) { map.removeLayer(m); });
                    mapDeviceMarkers = [];

                    allDevices.forEach(function(dev) {
                        var statusClass = dev.status === 'online' ? 'status-online' :
                                          dev.status === 'offline' ? 'status-offline' : 'status-unknown';
                        var markerColor = dev.status === 'online' ? '#28a745' :
                                          dev.status === 'offline' ? '#dc3545' : '#ffc107';

                        var devIcon = L.divIcon({
                            html: '<div style="background:' + markerColor + ';width:26px;height:26px;border-radius:50%;border:3px solid #714B67;box-shadow:0 2px 6px rgba(0,0,0,.35);display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;">🏢</div>',
                            iconSize:[26,26], iconAnchor:[13,13], className:''
                        });
                        var marker = L.marker([dev.lat, dev.lng], {icon:devIcon}).addTo(map);

                        // Geofence circle
                        if (dev.geofence_radius > 0) {
                            var circle = L.circle([dev.lat, dev.lng], {
                                radius: dev.geofence_radius,
                                color: '#714B67',
                                fillColor: '#714B67',
                                fillOpacity: 0.08,
                                weight: 1.5,
                                dashArray: '5, 5'
                            }).addTo(map);
                            mapDeviceMarkers.push(circle);
                        }

                        // Popup
                        var statusLabel = dev.status === 'online' ? 'Online' :
                                          dev.status === 'offline' ? 'Offline' : 'Unknown';
                        var popupHtml = '<div class="device-popup">' +
                            '<h3>🏢 ' + dev.name + '</h3>' +
                            '<table>' +
                            '<tr><td>Location:</td><td>' + (dev.location_name || 'N/A') + '</td></tr>' +
                            '<tr><td>Status:</td><td><span class="status-dot ' + statusClass + '"></span>' + statusLabel + '</td></tr>' +
                            '<tr><td>IP:</td><td>' + dev.ip + '</td></tr>' +
                            '<tr><td>Mode:</td><td>' + dev.connection_mode + '</td></tr>' +
                            '<tr><td>Users:</td><td>' + dev.user_count + '</td></tr>' +
                            '<tr><td>Records:</td><td>' + dev.record_count + '</td></tr>' +
                            '<tr><td>Storage:</td><td>' + dev.storage_pct + '%</td></tr>' +
                            (dev.geofence_radius ? '<tr><td>Geofence:</td><td>' + dev.geofence_radius + 'm</td></tr>' : '') +
                            '</table>' +
                            '<a class="btn-open" href="/odoo/biometric.device.details/' + dev.id + '" target="_blank">Open Device Form</a>' +
                            '</div>';
                        marker.bindPopup(popupHtml, {maxWidth: 300});
                        marker.bindTooltip('<b>🏢 ' + dev.name + '</b><br/>' + (dev.location_name || ''), {sticky:true, direction:'top'});

                        mapDeviceMarkers.push(marker);
                    });
                }

                // ══════════════════════════════════════════════════════════════
                // EMPLOYEE ATTENDANCE MARKERS
                // ══════════════════════════════════════════════════════════════
                function buildEmpMarkers(data) {
                    mapEmpMarkers.forEach(function(m) {
                        if (m.leaflet) map.removeLayer(m.leaflet);
                        if (m.outLeaflet) map.removeLayer(m.outLeaflet);
                        if (m.line) map.removeLayer(m.line);
                    });
                    mapEmpMarkers = [];

                    data.forEach(function(d) {
                        var col = empColor(d.emp_id);
                        var colL = empColorLight(d.emp_id);
                        var srcClass = 'src-' + d.source;
                        var markerSize = 36;

                        var inIconHtml;
                        if (d.emp_image_url) {
                            inIconHtml = '<div style="position:relative;width:' + markerSize + 'px;height:' + markerSize + 'px;">' +
                                '<div style="width:' + markerSize + 'px;height:' + markerSize + 'px;border-radius:50%;border:3px solid ' + col + ';box-shadow:0 2px 8px rgba(0,0,0,.35);overflow:hidden;background:#fff;">' +
                                '<img src="' + d.emp_image_url + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" onerror="this.parentElement.innerHTML=\'<div style=\\\'width:100%;height:100%;border-radius:50%;background:' + col + ';display:flex;align-items:center;justify-content:center;color:#fff;font-size:13px;font-weight:700;\\\'>' + (d.emp_initials || '?') + '</div>\'"/>' +
                                '</div>' +
                                '<div style="position:absolute;bottom:-2px;right:-2px;background:#fff;border-radius:50%;width:14px;height:14px;display:flex;align-items:center;justify-content:center;font-size:8px;box-shadow:0 1px 3px rgba(0,0,0,.3);border:1px solid #ddd;">' + d.source_icon + '</div>' +
                                '</div>';
                        } else {
                            inIconHtml = '<div style="position:relative;width:' + markerSize + 'px;height:' + markerSize + 'px;">' +
                                '<div style="width:' + markerSize + 'px;height:' + markerSize + 'px;border-radius:50%;border:3px solid ' + col + ';box-shadow:0 2px 8px rgba(0,0,0,.35);background:' + col + ';display:flex;align-items:center;justify-content:center;color:#fff;font-size:13px;font-weight:700;">' + (d.emp_initials || '?') + '</div>' +
                                '<div style="position:absolute;bottom:-2px;right:-2px;background:#fff;border-radius:50%;width:14px;height:14px;display:flex;align-items:center;justify-content:center;font-size:8px;box-shadow:0 1px 3px rgba(0,0,0,.3);border:1px solid #ddd;">' + d.source_icon + '</div>' +
                                '</div>';
                        }
                        var inIcon = L.divIcon({
                            html: inIconHtml,
                            iconSize:[markerSize, markerSize],
                            iconAnchor:[markerSize/2, markerSize/2],
                            className: ''
                        });
                        var inM = L.marker([d.in_lat, d.in_lng], {icon:inIcon}).addTo(map);

                        var cIn = d.check_in ? new Date(d.check_in).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : 'N/A';
                        var cOut = d.check_out ? new Date(d.check_out).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '⏳ Still In';
                        var distCls = d.distance > 500 ? 'dist-far' : d.distance > 200 ? 'dist-warn' : 'dist-ok';
                        var locTag = d.inside_office ? '✅ Inside Office' : '🔴 Outside Office';

                        var tt = '<div class="tt-name" style="color:' + col + '">' + d.emp_name + '</div>' +
                            (d.emp_job ? '<div class="tt-row">' + d.emp_job + '</div>' : '') +
                            '<div class="tt-row"><b>Dept:</b> ' + d.department_name + '</div>' +
                            '<div class="tt-row"><b>In:</b> ' + cIn + ' → <b>Out:</b> ' + cOut + '</div>' +
                            '<div class="tt-row"><span class="badge-src ' + srcClass + '">' + d.source_icon + ' ' + d.source + '</span> ' + locTag + '</div>' +
                            (d.distance > 0 ? '<div class="tt-row ' + distCls + '"><b>📏 ' + d.distance + 'm</b> from office</div>' : '') +
                            (d.emp_badge ? '<div class="tt-row"><b>ZK ID:</b> ' + d.emp_badge + '</div>' : '') +
                            (d.emp_mobile ? '<div class="tt-row"><b>📱</b> ' + d.emp_mobile + '</div>' : '');
                        inM.bindTooltip(tt, {sticky:true, className:'emp-tooltip', direction:'top', offset:[0,-12]});

                        var popup = '<div style="min-width:200px;"><b style="color:' + col + '">' + d.emp_name + '</b>' +
                            (d.emp_job ? '<br/><small>' + d.emp_job + ' — ' + d.department_name + '</small>' : '') +
                            '<hr style="margin:4px 0"/>' +
                            '<table style="font-size:12px;">' +
                            '<tr><td>🕐 In:</td><td>' + cIn + '</td></tr>' +
                            '<tr><td>🕐 Out:</td><td>' + cOut + '</td></tr>' +
                            '<tr><td>Source:</td><td><span class="badge-src ' + srcClass + '">' + d.source_icon + ' ' + d.source + '</span></td></tr>' +
                            '<tr><td>Location:</td><td>' + locTag + '</td></tr>' +
                            (d.distance > 0 ? '<tr><td>Distance:</td><td class="' + distCls + '">' + d.distance + 'm</td></tr>' : '') +
                            (d.emp_mobile ? '<tr><td>Mobile:</td><td>' + d.emp_mobile + '</td></tr>' : '') +
                            (d.emp_badge ? '<tr><td>ZK ID:</td><td>' + d.emp_badge + '</td></tr>' : '') +
                            '</table></div>';
                        inM.bindPopup(popup, {maxWidth:300});

                        var entry = {leaflet: inM, data: d, outLeaflet: null, line: null};

                        if (d.has_checkout_gps) {
                            var outIcon = L.divIcon({
                                html: '<div style="background:' + colL + ';width:16px;height:16px;border-radius:50%;border:2px solid #fff;box-shadow:0 2px 4px rgba(0,0,0,.25);"></div>',
                                iconSize:[16,16], iconAnchor:[8,8], className:''
                            });
                            var outM = L.marker([d.out_lat, d.out_lng], {icon:outIcon}).addTo(map);
                            outM.bindPopup('<b>' + d.emp_name + '</b><br/>Check-out: ' + cOut);
                            outM.bindTooltip('<b>' + d.emp_name + '</b><br/>Check-out: ' + cOut, {sticky:true, className:'emp-tooltip', direction:'top'});
                            entry.outLeaflet = outM;
                            entry.line = L.polyline([[d.in_lat,d.in_lng],[d.out_lat,d.out_lng]], {color:col, weight:1.5, dashArray:'4,4', opacity:.6}).addTo(map);
                        }
                        mapEmpMarkers.push(entry);
                    });
                }

                // ══════════════════════════════════════════════════════════════
                // SIDEBAR: Devices section + Employees grouped by department
                // ══════════════════════════════════════════════════════════════
                function buildSidebar(data) {
                    var list = document.getElementById('emp-list');
                    list.innerHTML = '';

                    // ── Devices section (always visible) ──
                    if (allDevices.length > 0) {
                        var devSection = document.createElement('div');
                        var devHdr = document.createElement('div');
                        devHdr.className = 'section-header';
                        devHdr.innerHTML = '🏢 Devices <span class="cnt">' + allDevices.length + '</span>';
                        var devBody = document.createElement('div');
                        devBody.className = 'section-body';
                        devHdr.onclick = function() { devBody.classList.toggle('collapsed'); };
                        devSection.appendChild(devHdr);

                        allDevices.forEach(function(dev) {
                            var statusClass = dev.status === 'online' ? 'status-online' :
                                              dev.status === 'offline' ? 'status-offline' : 'status-unknown';
                            var card = document.createElement('div');
                            card.className = 'device-card';
                            card.innerHTML = '<h4><span class="status-dot ' + statusClass + '"></span>🏢 ' + dev.name + '</h4>' +
                                '<div class="meta">' +
                                (dev.location_name || 'No location') + ' | ' + dev.ip +
                                '<br/>Users: ' + dev.user_count + ' | Storage: ' + dev.storage_pct + '%' +
                                (dev.geofence_radius ? ' | Geofence: ' + dev.geofence_radius + 'm' : '') +
                                '</div>';
                            card.onclick = function() {
                                map.setView([dev.lat, dev.lng], 16);
                                document.querySelectorAll('.device-card, .emp-card').forEach(function(c) { c.classList.remove('active'); });
                                card.classList.add('active');
                            };
                            devBody.appendChild(card);
                        });
                        devSection.appendChild(devBody);
                        list.appendChild(devSection);
                    }

                    // ── Employees section ──
                    if (data.length === 0) {
                        list.innerHTML += '<div class="no-data"><i class="fa fa-map-marker"/>No GPS check-ins found for this date range.<br/><small>Try changing the date or filters.</small></div>';
                        return;
                    }

                    var empSection = document.createElement('div');
                    var empHdr = document.createElement('div');
                    empHdr.className = 'section-header';
                    empHdr.style.background = '#28a745';
                    empHdr.innerHTML = '👥 Team Check-ins <span class="cnt">' + data.length + '</span>';
                    var empBody = document.createElement('div');
                    empBody.className = 'section-body';
                    empHdr.onclick = function() { empBody.classList.toggle('collapsed'); };
                    empSection.appendChild(empHdr);

                    // Group by department
                    var groups = {};
                    data.forEach(function(d) {
                        var dk = d.department_name || 'No Department';
                        if (!groups[dk]) groups[dk] = [];
                        groups[dk].push(d);
                    });
                    var sortedKeys = Object.keys(groups).sort();
                    sortedKeys.forEach(function(deptName) {
                        var grp = document.createElement('div');
                        grp.className = 'dept-group';
                        var hdr = document.createElement('div');
                        hdr.className = 'dept-header';
                        hdr.innerHTML = '🏢 ' + deptName + ' <span class="cnt">' + groups[deptName].length + '</span>';
                        var body = document.createElement('div');
                        body.className = 'dept-body';
                        hdr.onclick = function() { body.classList.toggle('collapsed'); };
                        grp.appendChild(hdr);

                        groups[deptName].forEach(function(d) {
                            var col = empColor(d.emp_id);
                            var cIn = d.check_in ? new Date(d.check_in).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : 'N/A';
                            var cOut = d.check_out ? new Date(d.check_out).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '⏳';
                            var distCls = d.distance > 500 ? 'dist-far' : d.distance > 200 ? 'dist-warn' : 'dist-ok';
                            var locTag = d.inside_office ? '<span class="loc-tag tag-inside">Inside</span>' : '<span class="loc-tag tag-outside">Outside</span>';
                            var srcCls = 'src-' + d.source;

                            var avatarHtml;
                            if (d.emp_image_url) {
                                avatarHtml = '<img src="' + d.emp_image_url + '" style="width:28px;height:28px;border-radius:50%;border:2px solid ' + col + ';object-fit:cover;flex-shrink:0;" onerror="this.outerHTML=\'<div style=\\\'width:28px;height:28px;border-radius:50%;background:' + col + ';display:flex;align-items:center;justify-content:center;color:#fff;font-size:11px;font-weight:700;flex-shrink:0;\\\'>' + (d.emp_initials || '?') + '</div>\'"/>';
                            } else {
                                avatarHtml = '<div style="width:28px;height:28px;border-radius:50%;background:' + col + ';display:flex;align-items:center;justify-content:center;color:#fff;font-size:11px;font-weight:700;flex-shrink:0;">' + (d.emp_initials || '?') + '</div>';
                            }

                            var card = document.createElement('div');
                            card.className = 'emp-card';
                            card.style.borderLeftColor = col;
                            card.innerHTML = '<h4>' + avatarHtml + ' ' + d.emp_name +
                                ' <span class="badge-src ' + srcCls + '">' + d.source_icon + '</span></h4>' +
                                '<div class="meta">' + cIn + ' → ' + cOut + ' ' + locTag +
                                (d.distance > 0 ? ' <span class="' + distCls + '">📏' + d.distance + 'm</span>' : '') +
                                (d.emp_job ? '<br/>' + d.emp_job : '') +
                                '</div>';
                            card.onclick = function() {
                                map.setView([d.in_lat, d.in_lng], 16);
                                mapEmpMarkers.forEach(function(m) {
                                    if (m.data.id === d.id) m.leaflet.openPopup();
                                });
                                document.querySelectorAll('.device-card, .emp-card').forEach(function(c) { c.classList.remove('active'); });
                                card.classList.add('active');
                            };
                            body.appendChild(card);
                        });
                        grp.appendChild(body);
                        empSection.appendChild(grp);
                    });
                    empSection.appendChild(empBody);
                    list.appendChild(empSection);
                }

                // ── Stats ──
                function updateStats(data) {
                    var devCount = allDevices.length;
                    var total = data.length;
                    var inside = data.filter(function(d) { return d.inside_office; }).length;
                    var outside = total - inside;
                    document.getElementById('stats-bar').innerHTML =
                        '<span class="stat-chip stat-devices">🏢 ' + devCount + ' Devices</span>' +
                        '<span class="stat-chip stat-total">👥 ' + total + ' Check-ins</span>' +
                        '<span class="stat-chip stat-in">✅ ' + inside + ' Inside</span>' +
                        '<span class="stat-chip stat-out">📍 ' + outside + ' Outside</span>';
                }

                // ══════════════════════════════════════════════════════════════
                // FILTERING
                // ══════════════════════════════════════════════════════════════
                function getFilteredData() {
                    var search = document.getElementById('search-input').value.toLowerCase().trim();
                    var deptId = document.getElementById('dept-filter').value;
                    var filtered = allMarkers;

                    if (currentToggle === 'in') {
                        filtered = filtered.filter(function(d) { return d.inside_office; });
                    } else if (currentToggle === 'out') {
                        filtered = filtered.filter(function(d) { return !d.inside_office; });
                    }

                    if (deptId) {
                        var did = parseInt(deptId);
                        filtered = filtered.filter(function(d) { return d.department_id === did; });
                    }

                    if (search) {
                        filtered = filtered.filter(function(d) {
                            return (d.emp_name || '').toLowerCase().indexOf(search) >= 0 ||
                                   (d.emp_mobile || '').toLowerCase().indexOf(search) >= 0 ||
                                   (d.emp_badge || '').toLowerCase().indexOf(search) >= 0;
                        });
                    }
                    return filtered;
                }

                function applyFilters() {
                    var data = getFilteredData();
                    buildEmpMarkers(data);
                    buildSidebar(data);
                    updateStats(data);
                    fitMapBounds(data);
                }

                // ── Toggle ──
                function setToggle(mode) {
                    currentToggle = mode;
                    document.getElementById('tog-all').className = 'toggle-btn' + (mode==='all' ? ' active-all' : '');
                    document.getElementById('tog-devices').className = 'toggle-btn' + (mode==='devices' ? ' active-devices' : '');
                    document.getElementById('tog-in').className = 'toggle-btn' + (mode==='in' ? ' active-in' : '');
                    document.getElementById('tog-out').className = 'toggle-btn' + (mode==='out' ? ' active-out' : '');
                    applyFilters();
                }

                // ── Date range ──
                function applyDateRange() {
                    var df = document.getElementById('date-from').value;
                    var dt = document.getElementById('date-to').value;
                    if (df || dt) {
                        window.location.href = '/zkteco/attendance/map?date_from=' + encodeURIComponent(df || '') + '&date_to=' + encodeURIComponent(dt || df || '');
                    }
                }

                // ── Fit map bounds ──
                function fitMapBounds(data) {
                    var allPins = [];
                    // Include device markers
                    if (currentToggle === 'all' || currentToggle === 'devices') {
                        allDevices.forEach(function(d) { allPins.push(L.marker([d.lat, d.lng])); });
                    }
                    // Include employee markers
                    if (currentToggle !== 'devices') {
                        mapEmpMarkers.forEach(function(m) {
                            allPins.push(m.leaflet);
                            if (m.outLeaflet) allPins.push(m.outLeaflet);
                        });
                    }
                    if (allPins.length > 0) {
                        map.fitBounds(L.featureGroup(allPins).getBounds().pad(0.2));
                    }
                }

                // ── Search on type ──
                document.getElementById('search-input').addEventListener('input', function() {
                    applyFilters();
                });

                // ══════════════════════════════════════════════════════════════
                // INITIAL RENDER
                // ══════════════════════════════════════════════════════════════
                buildDeviceMarkers();
                applyFilters();
/**/
